from typing import Callable, List, Optional, Tuple, Dict

Predicate = Callable[[int], bool]
Profile = Tuple[bool, ...]


def profile(preds: List[Predicate], state: int) -> Profile:
    return tuple(p(state) for p in preds)


def find_twin_pair(preds: List[Predicate],
                   states: List[int]) -> Optional[Tuple[int, int]]:
    seen: Dict[Profile, int] = {}
    for s in states:
        sig = profile(preds, s)
        if sig in seen and seen[sig] != s:
            return (seen[sig], s)
        seen.setdefault(sig, s)
    return None


if __name__ == "__main__":
    preds: List[Predicate] = [
        lambda a: a % 2 == 0,
        lambda a: a % 3 == 0,
        lambda a: a >= 5,
    ]
    states = list(range(9))   # 9 > 2**3 = 8 -> twins guaranteed
    pair = find_twin_pair(preds, states)
    print("twin pair:", pair)
    if pair:
        a, b = pair
        print("profile(a) =", profile(preds, a))
        print("profile(b) =", profile(preds, b))

