from typing import Callable, Dict, List, Optional, Tuple, Union

Predicate = Callable[[int], bool]


@dataclass
class Nil:
    pass


@dataclass
class Node:
    pred: Predicate
    if_false: "AdaptiveObs"
    if_true: "AdaptiveObs"


AdaptiveObs = Union[Nil, Node]


def transcript(tree: AdaptiveObs, state: int) -> Tuple[bool, ...]:
    answers: List[bool] = []
    node = tree
    while isinstance(node, Node):
        b = node.pred(state)
        answers.append(b)
        node = node.if_true if b else node.if_false
    return tuple(answers)


if __name__ == "__main__":
    tree = Node(
        pred=lambda a: a >= 4,
        if_false=Node(lambda a: a % 2 == 0,
                      Node(lambda a: a == 1, Nil(), Nil()),
                      Node(lambda a: a == 0, Nil(), Nil())),
        if_true=Node(lambda a: a % 2 == 0,
                     Node(lambda a: a == 5, Nil(), Nil()),
                     Node(lambda a: a == 4, Nil(), Nil())),
    )
    states = list(range(9))
    ts = {s: transcript(tree, s) for s in states}
    print("distinct transcripts:", len(set(ts.values())), "<= 8")
    seen: Dict[Tuple[bool, ...], int] = {}
    for s in states:
        if ts[s] in seen:
            print("adaptive twins:", (seen[ts[s]], s), "->", ts[s])
            break
        seen[ts[s]] = s

