def of_preds(preds: List[Predicate]) -> AdaptiveObs:
    if not preds:
        return Nil()
    sub = of_preds(preds[1:])
    return Node(pred=preds[0], if_false=sub, if_true=sub)


def transcript(tree: AdaptiveObs, state: int) -> Tuple[bool, ...]:
    answers: List[bool] = []
    node = tree
    while isinstance(node, Node):
        b = node.pred(state)
        answers.append(b)
        node = node.if_true if b else node.if_false
    return tuple(answers)


def profile(preds: List[Predicate], state: int) -> Tuple[bool, ...]:
    return tuple(p(state) for p in preds)


if __name__ == "__main__":
    n = 4
    preds = [(lambda i: (lambda a: bool((a >> i) & 1)))(i) for i in range(n)]
    lazy = of_preds(preds)
    ok = all(profile(preds, s) == transcript(lazy, s) for s in range(2 ** n))
