from typing import Callable, Dict, List, Optional, Tuple

Predicate = Callable[[int], bool]
Profile = Tuple[bool, ...]


def profile(preds: List[Predicate], state: int) -> Profile:
    """The n-tuple of predicate values for `state`."""
    return tuple(p(state) for p in preds)


def find_twin_pair(preds: List[Predicate],
                   states: List[int]) -> Optional[Tuple[int, int]]:
    """Return a distinct pair with identical profiles, or None.

    Guaranteed non-None when len(states) > 2 ** len(preds).
    """
    seen: Dict[Profile, int] = {}
    for s in states:
        sig = profile(preds, s)
        if sig in seen and seen[sig] != s:
            return (seen[sig], s)
        seen.setdefault(sig, s)
    return None

from dataclasses import dataclass
from typing import Callable, List, Tuple, Union

Predicate = Callable[[int], bool]


@dataclass
class Nil:
    """Depth-0 adaptive system (leaf)."""


@dataclass
class Node:
    """Ask `pred`; branch into `if_false` / `if_true` on the answer."""
    pred: Predicate
    if_false: "AdaptiveObs"
    if_true: "AdaptiveObs"


AdaptiveObs = Union[Nil, Node]


def transcript(tree: AdaptiveObs, state: int) -> Tuple[bool, ...]:
    """The length-n answer transcript of `state` under the decision tree."""
    answers: List[bool] = []
    node: AdaptiveObs = tree
    while isinstance(node, Node):
        b = node.pred(state)
        answers.append(b)
        node = node.if_true if b else node.if_false
    return tuple(answers)

